 final _barcode=TextEditingController(),_search=TextEditingController(),_tendered=TextEditingController(),_reference=TextEditingController(); final _cart=<int,_CartLine>{}; final _queue=OfflineSaleQueue(); Timer? _retryTimer;
 List<Map<String,dynamic>> _products=[],_tables=[]; String _orderType='Dine In',_payment='Cash',_status=''; int? _tableId,_pendingCount,_lastOrderId; double _taxPercent=0; String _currency='Rs.'; bool _loading=true,_saving=false,_syncing=false,_printing=false;
 @override void initState(){super.initState();WidgetsBinding.instance.addObserver(this);_tendered.text='0';_loadCatalog();_refreshQueue();_retryTimer=Timer.periodic(const Duration(seconds:30),(_)=>_syncQueue(silent:true));}
 Future<void> _loadCatalog()async{try{final p=await widget.api.products(),t=await widget.api.tables(),s=await widget.api.settings();if(!mounted)return;setState((){_products=p.whereType<Map<String,dynamic>>().where((x)=>x['available']==true).toList();_tables=t.whereType<Map<String,dynamic>>().where((x)=>x['active']==true&&x['status']=='Available').toList();_taxPercent=(s['taxPercent'] as num?)?.toDouble()??0;_currency='${s['currencySymbol']??'Rs.'}';_loading=false;});}catch(_){if(mounted)setState(()=>_loading=false);}}
