ding.';});}}
 @override void didChangeAppLifecycleState(AppLifecycleState state){if(state==AppLifecycleState.resumed)_syncQueue(silent:true);}
 @override void dispose(){WidgetsBinding.instance.removeObserver(this);_retryTimer?.cancel();_barcode.dispose();_search.dispose();_tendered.dispose();_reference.dispose();super.dispose();}
