title:Text(l.name),subtitle:Text('$_currency ${l.price.toStringAsFixed(0)} × ${l.quantity}'),trailing:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:()=>setState((){if(l.quantity>1)l.quantity--;else _cart.remove(l.id);}),icon:const Icon(Icons.remove)),IconButton(onPressed:()=>_add(_products.firstWhere((p)=>(p['id'] as num).toInt()==l.id)),icon:const Icon(Icons.add))]))])),DropdownButtonFormField<String>(value:_orderType,items:const ['Dine In','Takeaway','Delivery'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(x)=>setState((){_orderType=x!;if(_orderType!='Dine In')_tableId=null;}),decoration:const InputDecoration(labelText:'Order type')),if(_orderType=='Dine In')DropdownButtonFormField<int>(value:_tableId,items:_tables.map((t)=>DropdownMenuItem(value:(t['id'] as num).toInt(),child:Text('${t['name']}'))).toList(),onChanged:(x)=>setState(()=>_tableId=x),decoration:const InputDecoration(labelText:'Table')),DropdownButtonFormField<String>(value:_payment,items:const ['Cash','Card','Online'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(x)=>setState((){_payment=x!;if(_payment!='Cash')_tendered.text=_total.toStringAsFixed(2);}),decoration:const InputDecoration(labelText:'Payment')),if(_payment=='Cash')TextField(controller:_tendered,keyboardType:const TextInputType.numberWithOptions(decimal:true),onChanged:(_)=>setState((){}),decoration:InputDecoration(labelText:'Cash tendered',prefixText:'$_currency ')),if(_payment=='Card'||_payment=='Online')TextField(controller:_reference,decoration:const InputDecoration(labelText:'Payment reference',border:OutlineInputBorder())),const SizedBox(height:12),Text('Subtotal: $_currency ${_subtotal.toStringAsFixed(2)}'),Text('Tax (${_taxPercent.toStringAsFixed(2)}%): $_currency ${_tax.toStringAsFixed(2)}'),Text('TOTAL: $_currency ${_total.toStringAsFixed(2)}',style:Theme.of(context).textTheme.titleLarge),if(_payment=='Cash')Text('Change: $_currency ${_change.toStringAsFixed(2)}'),const SizedBox(height:12),FilledButton.icon(onPressed:_saving?null:_completeSale,icon:const Icon(Icons.point_of_sale),label:Text(_saving?'Processing...':'Complete Sale')),if(_lastOrderId!=null)OutlinedButton.icon(onPressed:_printing?null:()=>_printReceipt(_lastOrderId!),icon:const Icon(Icons.print),label:Text(_printing?'Printing...':'Reprint Receipt')),if(_status.isNotEmpty)Padding(padding:const EdgeInsets.only(top:8),child:Text(_status))])))]));}
